		private void LoadWazaFx() {
            if (_photoData.seqType != 1)
                return;

            if (_wazaEffectsTable == null)
                _wazaEffectsTable = new Dictionary<int, List<PhotoWazaEffect>>();

            if (_wazaEffectsTable.ContainsKey((int)_selectCategoryID))
            {
                foreach (PhotoWazaEffect wazaEffect in _wazaEffectsTable[(int)_selectCategoryID])
                    wazaEffect.Show();
                return;
            }

            _wazaEffectsTable.Add((int)_selectCategoryID, new List<PhotoWazaEffect>());
            List<CommandParam> commands = _iPtrSequenceSystem.FindCommands(CommandNo.ParticleCreate);
            EffectDatabase.SheetBattleEffectData[] battleEffectData = EffectManager.Instance.dbEffects.BattleEffectData;
            foreach (CommandParam command in commands)
            {
                if (_photoData.seqFrame < command.StartFrame || command.EndFrame < _photoData.seqFrame)
                    continue;

                if (!(command.Macro is ParticleCreate particleCreate))
                    continue;

                string fileName = ("effect/prefab/battle/" + System.IO.Path.GetFileNameWithoutExtension(particleCreate.file)).ToLower();
                EffectDatabase.SheetBattleEffectData fxParam = Array.Find(battleEffectData, x => x.AssetBundleName == fileName);
                if (fxParam == null)
                {
                    ContestUtils.EmitLog("Not Found Effect!!!! : " + fileName, LogType.Error);
                    continue;
                }

                CON_PHOTO_FX_DATA fxData = Array.Find(_photoData.fxDatas, x => x.groupNo == command.GroupNo);
                CreateEffectByFilePath(fxData, fxParam);
            }
        }
