                Vector3 position = new Vector3(fxData.fxPositionX, fxData.fxPositionY, fxData.fxPositionZ) + _offsetPos;
                wazaEffect.effectData = effectData;
                wazaEffect.fxInst = fxManager.Play(wazaEffect.effectData, position, Quaternion.Euler(fxData.fxRotX, fxData.fxRotY, fxData.fxRotZ), null, null);
                wazaEffect.fxInst.particleSystem.transform.localScale = new Vector3(fxData.fxScaleX, fxData.fxScaleY, fxData.fxScaleZ);
                wazaEffect.particlePlayTime = fxData.particlePlayTime;
                wazaEffect.Show();
                _wazaEffectsTable[(int)_selectCategoryID].Add(wazaEffect);
            });
        }
