            if (!string.IsNullOrEmpty(wazaSeqPath))
                SmartPoint.AssetAssistant.AssetManager.UnloadAssetBundle(wazaSeqPath);

            if (titleSprite != null)
            {
                UnityEngine.Object.DestroyImmediate(titleSprite);
                titleSprite = null;
            }

            if (photoFrameSpr != null)
            {
                UnityEngine.Object.DestroyImmediate(photoFrameSpr);
                photoFrameSpr = null;
            }
        }
		public UIContestPhoto() { }
		static UIContestPhoto() { }
		private class StageModel
		{
			public global::UnityEngine.GameObject modelObj;
			public string stageModelPath;
			public void Show(global::UnityEngine.Transform parentTransform) {
                modelObj.transform.SetParent(parentTransform);
                modelObj.SetActive(true);
            }
			public void Hide() {
                modelObj.SetActive(false);
                modelObj.transform.SetParent(GameManager.fieldObjectHolder);
            }
			public void Release() {
                UnityEngine.Object.Destroy(modelObj);
                modelObj = null;
                SmartPoint.AssetAssistant.AssetManager.UnloadAssetBundle(stageModelPath);
            }
			public StageModel() { }
		}
		private class PhotoPokemonModel
		{
			public global::BattlePokemonEntity pokeEntity;
			public global::UnityEngine.GameObject migawariObj;
			public string photoTargetModelPath;
			private bool IsMigawari { get { return migawariObj != null; } }
			public void Show(global::UnityEngine.Transform parentTransform) {
                // IsMigawari inlined (its flag 0x4cbb466), then a second null test (@017b8240)
                if (IsMigawari)
                {
                    if (migawariObj != null)
                    {
                        migawariObj.transform.SetParent(parentTransform);
                        migawariObj.SetActive(true);
                    }
                }
                else if (pokeEntity != null)
                {
                    pokeEntity.transform.SetParent(parentTransform);
                    pokeEntity.SetRenderActive(true);
                }
            }
			public void Hide() {
                Transform holder = GameManager.fieldObjectHolder;
                if (IsMigawari)
                {
                    if (migawariObj != null)
                    {
                        migawariObj.transform.SetParent(holder);
                        migawariObj.SetActive(false);
                    }
                }
                else if (pokeEntity != null)
                {
                    pokeEntity.transform.SetParent(holder);
                    pokeEntity.SetRenderActive(false);
                }
            }
			public void Release() {
                if (pokeEntity != null)
                {
                    UnityEngine.Object.Destroy(pokeEntity.gameObject);
                    pokeEntity = null;
                }

                if (migawariObj != null)
                {
                    UnityEngine.Object.Destroy(migawariObj);
                    migawariObj = null;
                }

                SmartPoint.AssetAssistant.AssetManager.UnloadAssetBundle(photoTargetModelPath);
            }
			public PhotoPokemonModel() { }
		}
		private class PhotoWazaEffect
		{
			public global::Effect.EffectData effectData;
			public global::Effect.EffectInstance fxInst;
			public float particlePlayTime;
			public void Show() {
                fxInst.gameObject.SetActive(true);
                ParticleSystem particleSystem = fxInst.particleSystem;
                particleSystem.Pause();
                particleSystem.Simulate(particlePlayTime);
                Animator[] animators = particleSystem.GetComponentsInChildren<Animator>();
                for (int i = 0; i < animators.Length; i++)
                {
                    Animator animator = animators[i];
                    animator.speed = 0f;
                    AnimatorStateInfo stateInfo = animator.GetCurrentAnimatorStateInfo(0);
                    // the division runs before get_shortNameHash (@017b4b54) = a local
                    float normalizedTime = particlePlayTime / stateInfo.length;
                    animator.Play(stateInfo.shortNameHash, 0, normalizedTime);
                }
            }
			public void Hide() {
                if (fxInst != null)
                    fxInst.gameObject.SetActive(false);
            }
			public PhotoWazaEffect() { }
		}
	}
}
